import{_ as a,c as t,o as n,ah as s}from"./chunks/framework.DUQY3pgt.js";const m=JSON.parse('{"title":"Labctl config reference","description":"","frontmatter":{"cli":"labctl"},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md","lastUpdated":1757364760000}'),o={name:"reference/config.md"};function l(i,e,d,c,p,r){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="labctl-config-reference" tabindex="-1">Labctl config reference <a class="header-anchor" href="#labctl-config-reference" aria-label="Permalink to “Labctl config reference”">​</a></h1><h2 id="cli-commands" tabindex="-1">CLI commands <a class="header-anchor" href="#cli-commands" aria-label="Permalink to “CLI commands”">​</a></h2><p>The CLI commands under <code>labctl config</code> allows you to interact with the <a href="/guide/config-engine">Config Engine</a>. It allows you to send commands to the router, render templates, or simply inspect one of the intermediate stages (variables &amp; templates).</p><details class="details custom-block"><summary><code>labctl config --help</code></summary><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Usage: labctl config &lt;command&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Render a template.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Flags:</span></span>
<span class="line"><span>  -h, --help                                 Show context-sensitive help.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -t, --topo=STRING                          topology file</span></span>
<span class="line"><span>  -p, --template-paths=TEMPLATE-PATHS,...    paths to search for templates</span></span>
<span class="line"><span>  -l, --template-list=TEMPLATE-LIST,...      template names to render</span></span>
<span class="line"><span>  -f, --filter=FILTER,...                    nodes to include</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Global Flags</span></span>
<span class="line"><span>  -d, --debug=INT          Enable debug mode.</span></span>
<span class="line"><span>      --settings=STRING    Settings yaml file.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>  config commit      Commit configuration on the node.</span></span>
<span class="line"><span>  config compare     Compare rendered templates to the node&#39;s config.</span></span>
<span class="line"><span>  config send        Send commands to the node (i.e. show)</span></span>
<span class="line"><span>  config template    Show rendered templates.</span></span>
<span class="line"><span>  config vars        Show variable inputs.</span></span></code></pre></div></details><p>The available commands include</p><h3 id="config-vars" tabindex="-1">config vars <a class="header-anchor" href="#config-vars" aria-label="Permalink to “config vars”">​</a></h3><p>The <code>config vars</code> command will prepare all the variables required for templating and display them on the console. This will not attempt to render any template</p><h3 id="config-template" tabindex="-1">config template <a class="header-anchor" href="#config-template" aria-label="Permalink to “config template”">​</a></h3><p>The <code>config template</code> command will render the templates and display the output on the terminal. This allows you to test your templates without sending anyting to the nodes</p><h3 id="config-compare" tabindex="-1">config compare <a class="header-anchor" href="#config-compare" aria-label="Permalink to “config compare”">​</a></h3><p>The <code>config compare</code> command will render the template and send it to the node with a compare transaction. At the end of the transaction the changes will be discarded. This allows you to see what changes the template in question will have on the node&#39;s configuration</p><p>Note: This relies on the capability of the target node to support transactions.</p><h3 id="config-commit" tabindex="-1">config commit <a class="header-anchor" href="#config-commit" aria-label="Permalink to “config commit”">​</a></h3><p>The <code>config commit</code> command will render the templates and commit the configuration to the target node.</p><h3 id="config-send" tabindex="-1">config send <a class="header-anchor" href="#config-send" aria-label="Permalink to “config send”">​</a></h3><p>The <code>config send</code> command will render the templates and send the commands to the target node without any transactions. This allows you to do show commands on the target node.</p><h2 id="cli-flags" tabindex="-1">CLI flags <a class="header-anchor" href="#cli-flags" aria-label="Permalink to “CLI flags”">​</a></h2><p>The following flags are available for the config commands</p><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th></th><th></th><th>Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--topo</code></td><td><code>-t</code></td><td>✔</td><td>the topology file</td></tr><tr><td style="text-align:left;"><code>--template-paths</code></td><td><code>-p</code></td><td>✔</td><td>paths to search for templates (in order)</td></tr><tr><td style="text-align:left;"><code>--template-list</code></td><td><code>-l</code></td><td>✔</td><td>template names to render</td></tr><tr><td style="text-align:left;"><code>--filter</code></td><td><code>-f</code></td><td></td><td>nodes to include</td></tr><tr><td style="text-align:left;"><code>--debug</code></td><td><code>-d</code></td><td></td><td>debug count, i.e. <code>-d</code>, <code>-ddd</code> or <code>--debug=3</code></td></tr><tr><td style="text-align:left;"><code>--settings</code></td><td></td><td></td><td>Settings file</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><p><code>labctl config vars</code></p>`,21)])])}const f=a(o,[["render",l]]);export{m as __pageData,f as default};
